<script setup lang="ts">
import { onMounted } from 'vue';import{storeToRefs}from'pinia';import{RouterLink}from'vue-router';import OrderScenarioBar from '../components/OrderScenarioBar.vue';import OrderFulfillmentSubnav from '../components/OrderFulfillmentSubnav.vue';import{useOrderStore}from'../runtime/order-store';import'./order-views.css';const store=useOrderStore();const{differences,loading,error,scenario,actor}=storeToRefs(store);const money=(v:number)=>`¥${(v/100).toFixed(2)}`;onMounted(()=>store.loadDifferences())
</script>
<template><section class="order-page"><header class="order-page-header"><div><p class="eyebrow">ORD-004 · 短装处理</p><h1>差异单</h1><p>只记录显式短装结案；退款等待退单与资金切片。</p></div><OrderScenarioBar :scenario="scenario" :role="actor.role" @scenario="async v=>{await store.setScenario(v);await store.loadDifferences()}" @role="async v=>{await store.setRole(v);await store.loadDifferences()}"/></header><OrderFulfillmentSubnav/><section class="order-panel"><div v-if="loading" class="order-state"><strong>正在加载差异单…</strong></div><div v-else-if="error" class="order-state error"><strong>差异单加载失败</strong><p>{{ error }}</p></div><div v-else-if="!differences.length" class="order-state"><strong>暂无差异单</strong></div><div v-else class="order-table-wrap"><table class="order-table"><thead><tr><th>差异单号</th><th>创建时间</th><th>客户</th><th class="order-money">差异金额</th><th>状态</th><th>差异原因</th></tr></thead><tbody><tr v-for="item in differences" :key="item.id"><td><RouterLink :to="`/orders/differences/${item.id}`">{{ item.differenceNo }}</RouterLink></td><td>{{ item.createdAt.slice(0,16).replace('T',' ') }}</td><td>{{ item.customerSnapshot.name }}</td><td class="order-money">{{ money(item.differenceAmountCents) }}</td><td>{{ item.status==='pending-confirmation'?'待确认':item.status==='confirmed'?'已确认':'已作废' }}</td><td>{{ item.reason }}</td></tr></tbody></table></div></section></section></template>
